<?php
/** Proof — vendor credits (spec "Proof", 5): issued, applied, the bill's balance falls; void refused while applied. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ap_fixture();
$V = mk_vendor('SMOKE Credit Vendor', ['expense_account' => account_id('6200')]);
$W = mk_vendor('SMOKE Other Credit Vendor');
$bill = ready_bill($V, [['Hosting, March', '1', '200.00']], ['vendor_ref' => 'CV-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-01']);
$wbill = ready_bill($W, [['Their bill', '1', '80.00']], ['vendor_ref' => 'CW-1', 'bill_date' => '2026-06-01', 'due_date' => '2026-07-01']);
echo "1. A vendor credit against a bill\n";
$body = page($bea, '/vendor-credits/new?bill=' . $bill)['body'];
ok(str_contains($body, 'id="vendor-credit-form-against"') && str_contains($body, 'value="Hosting, March"') && str_contains($body, 'id="vendor-credit-form-field-vendor"'), 'the form from a bill is prefilled with its lines and says "Against …"');
$since = last_activity_id();
[$c, $b] = act($bea, '/vendor-credits/save.php', ['vendor' => $V, 'bill' => $bill, 'vendor_ref' => 'CN-77', 'credit_date' => '2026-06-10', 'reason' => 'SMOKE downtime credit', 'lines' => json_encode([['description' => 'Downtime credit', 'quantity' => '1', 'unit_price' => '50.00', 'expense_account' => '6200']])]);
$vc = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $vc > 0 && ($b['location'] ?? '') === '/vendor-credits/' . $vc . '?notice=saved' && preg_match('/^VC-\d{5,6}$/', (string) ($b['number'] ?? '')) === 1, "vendor_credit_draft: 200, record_id $vc, a number at creation (" . ($b['number'] ?? '?') . ')');
$row = q('SELECT * FROM vendor_credits WHERE id = :c', ['c' => $vc])[0];
ok($row['status'] === 'draft' && $row['total'] === '50.00' && (int) $row['bill_id'] === $bill && $row['vendor_ref'] === 'CN-77' && $row['currency'] === 'USD', 'a draft against the bill, 50.00, USD');
ok(count(activity('vendor_credit.draft', $since)) === 1 && (int) activity('vendor_credit.draft', $since)[0]['vendor_id'] === $V, 'vendor_credit.draft logged with vendor_id');
[$c, $b] = act($bea, '/vendor-credits/line-save.php', ['vendor_credit' => $vc, 'description' => 'Extra', 'quantity' => '1', 'unit_price' => '25.00', 'expense_account' => '6200']);
$ln = (int) ($b['record_id'] ?? 0);
ok($c === 200 && (string) one('SELECT total FROM vendor_credits WHERE id = :c', ['c' => $vc]) === '75.00', 'a second line: the total follows (75.00)');
[$c, $b] = act($bea, '/vendor-credits/line-save.php', ['vendor_credit' => $vc, 'line' => $ln, 'quantity' => '2']);
ok($c === 200 && (string) one('SELECT total FROM vendor_credits WHERE id = :c', ['c' => $vc]) === '100.00', 'a changed line keeps what was not sent (2 × 25.00): 100.00');
[$c, $b] = act($bea, '/vendor-credits/line-remove.php', ['vendor_credit' => $vc, 'line' => $ln]);
ok($c === 200 && (string) one('SELECT total FROM vendor_credits WHERE id = :c', ['c' => $vc]) === '50.00', 'removed: back to 50.00');
$r = req('POST', '/vendor-credits/line-save.php', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: vendor-credit-lines'], 'form' => ['vendor_credit' => $vc, 'description' => 'Htmx', 'quantity' => '1', 'unit_price' => '1', 'csrf_token' => csrf_of(page($bea, '/')['body'])]]);
ok($r['code'] === 200 && str_starts_with(trim($r['body']), '<div id="vendor-credit-lines"') && str_contains($r['body'], 'id="vendor-credit-totals" hx-swap-oob="true"'), 'under HTMX a line write re-renders #vendor-credit-lines with the totals out of band');
act($bea, '/vendor-credits/line-remove.php', ['vendor_credit' => $vc, 'line' => (int) one('SELECT max(id) FROM vendor_credit_lines WHERE vendor_credit_id = :c', ['c' => $vc])]);
[$c, $b] = act($bea, '/vendor-credits/save.php', ['vendor' => $V, 'bill' => $wbill, 'lines' => '[]']);
ok($c === 422 && isset(fields($b)['bill']), 'a bill of another vendor: 422 naming the bill');
echo "2. Issue\n";
[$c, $b] = act($bea, '/vendor-credits/issue.php', ['vendor_credit' => $vc]);
ok($c === 403, 'the Bookkeeper issuing: 403 (ap.approve)');
$since = last_activity_id();
[$c, $b] = act($carl, '/vendor-credits/issue.php', ['vendor_credit' => $vc, 'apply_to' => $bill]);
ok($c === 200 && ($b['location'] ?? '') === '/vendor-credits/' . $vc . '?notice=issued', 'vendor_credit_issue by the Controller: 200');
$row = q('SELECT * FROM vendor_credits WHERE id = :c', ['c' => $vc])[0];
$jl = array_column(q('SELECT a.code, l.debit, l.credit, l.vendor_id FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $row['journal_entry_id']]), null, 'code');
ok($row['status'] === 'issued' && $row['amount_applied'] === '50.00' && $row['balance'] === '0.00' && $jl['2000']['debit'] === '50.00' && (int) $jl['2000']['vendor_id'] === $V && $jl['6200']['credit'] === '50.00', 'issued and applied at once: DR 2000 (the vendor) 50.00 / CR 6200 50.00');
$x = bill_row($bill);
ok($x['amount_credited'] === '50.00' && $x['status'] === 'partially_paid' && $x['balance_due'] === '150.00', 'the bill: credited 50.00, partly paid, 150.00 owed');
$l = activity('vendor_credit.issue', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['amount'] === '50.00' && $a['currency'] === 'USD' && str_starts_with($a['journal_entry_number'], 'JE-') && (int) $l['vendor_id'] === $V && count(activity('vendor_credit.apply', $since)) === 1, 'vendor_credit.issue logs the amount, currency, entry number; vendor_credit.apply too');
echo "3. Apply, unapply, void\n";
[$c, $b] = act($carl, '/vendor-credits/void.php', ['vendor_credit' => $vc, 'reason' => 'SMOKE x']);
ok($c === 422 && str_contains(msg($b), 'is applied; unapply it first'), 'void refused while applied: "… unapply it first"');
[$c, $b] = act($bea, '/vendor-credits/unapply.php', ['vendor_credit' => $vc, 'bill' => $bill]);
ok($c === 200 && bill_row($bill)['amount_credited'] === '0.00' && bill_row($bill)['balance_due'] === '200.00' && bill_row($bill)['status'] === 'approved', 'unapply: the bill owes 200.00 again');
[$c, $b] = act($bea, '/vendor-credits/unapply.php', ['vendor_credit' => $vc, 'bill' => $bill]);
ok($c === 422 && str_contains(msg($b), 'is not applied to that bill'), 'unapplying what is not applied: 422');
[$c, $b] = act($bea, '/vendor-credits/apply.php', ['vendor_credit' => $vc, 'bill' => $bill, 'amount' => '70']);
ok($c === 422 && str_contains(msg($b), 'more would exceed it'), 'applying more than the credit: 422 in the guard\'s words');
[$c, $b] = act($bea, '/vendor-credits/apply.php', ['vendor_credit' => $vc, 'bill' => $wbill]);
ok($c === 422 && str_contains(msg($b), 'is from another vendor than bill'), 'another vendor\'s bill: 422 "… is from another vendor …"');
[$c, $b] = act($bea, '/vendor-credits/apply.php', ['vendor_credit' => $vc, 'bill' => $bill, 'amount' => '20']);
ok($c === 200 && bill_row($bill)['amount_credited'] === '20.00' && bill_row($bill)['balance_due'] === '180.00', 'a partial application (20.00): the bill owes 180.00');
[$c, $b] = act($bea, '/vendor-credits/apply.php', ['vendor_credit' => $vc, 'bill' => $bill]);
ok($c === 200 && ($b['amount'] ?? '') === '30.00' && bill_row($bill)['balance_due'] === '150.00', 'apply with no amount: what fits (the 30.00 left); the bill owes 150.00');
$after = bill_row($bill);
ok($after['amount_credited'] === '50.00', 'two applications add up on the same bill (50.00)');
[$c, $b] = act($bea, '/vendor-credits/apply.php', ['vendor_credit' => $vc, 'bill' => $bill]);
ok($c === 422 && str_contains(msg($b), 'nothing to apply'), 'a fully applied credit: "There is nothing to apply"');
act($bea, '/vendor-credits/unapply.php', ['vendor_credit' => $vc, 'bill' => $bill]);
[$c, $b] = act($bea, '/vendor-credits/void.php', ['vendor_credit' => $vc, 'reason' => 'SMOKE x']);
ok($c === 403, 'a Bookkeeper voiding: 403');
$since = last_activity_id();
[$c, $b] = act($carl, '/vendor-credits/void.php', ['vendor_credit' => $vc, 'reason' => 'SMOKE issued in error']);
ok($c === 200 && (string) one('SELECT status FROM vendor_credits WHERE id = :c', ['c' => $vc]) === 'void' && (int) one('SELECT count(*) FROM journal_entries WHERE reversal_of = :e', ['e' => $row['journal_entry_id']]) === 1 && count(activity('vendor_credit.void', $since)) === 1, 'unapplied, a vendor credit is voided by the Controller: its entry reversed; logged');
[$c, $b] = act($carl, '/vendor-credits/void.php', ['vendor_credit' => $vc, 'reason' => 'again']);
ok($c === 422, 'a void credit is not voided again');
[$c, $b] = act($bea, '/vendor-credits/apply.php', ['vendor_credit' => $vc, 'bill' => $bill, 'amount' => '10']);
ok($c === 422 && str_contains(msg($b), 'is void, not issued'), 'a void credit takes no application');
echo "4. A credit with no bill, delete, the pages\n";
$vc2 = (int) act($bea, '/vendor-credits/save.php', ['vendor' => $V, 'lines' => json_encode([['description' => 'Standalone', 'quantity' => '1', 'unit_price' => '15.00']])])[1]['record_id'];
ok((int) one('SELECT expense_account_id FROM vendor_credit_lines WHERE vendor_credit_id = :c', ['c' => $vc2]) === account_id('6200'), 'a credit line with no account takes the vendor\'s expense account');
[$c, $b] = act($bea, '/vendor-credits/save.php', ['vendor_credit' => $vc2, 'reason' => 'SMOKE edited', 'vendor_ref' => 'ZZ-9']);
ok($c === 200 && (string) one('SELECT reason FROM vendor_credits WHERE id = :c', ['c' => $vc2]) === 'SMOKE edited', 'vendor_credit_update changes a draft\'s head');
$since = last_activity_id();
[$c, $b] = act($bea, '/vendor-credits/delete.php', ['vendor_credit' => $vc2]);
ok($c === 200 && one('SELECT 1 FROM vendor_credits WHERE id = :c', ['c' => $vc2]) === false && count(activity('vendor_credit.delete', $since)) === 1, 'vendor_credit_delete removes a draft; logged');
[$c, $b] = act($bea, '/vendor-credits/delete.php', ['vendor_credit' => $vc]);
ok($c === 422 && str_contains(msg($b), 'only a draft is deleted'), 'a void credit is not deleted');
$body = page($bea, '/vendor-credits/')['body'];
ok(str_contains($body, 'id="vendor-credit-card-' . $vc . '"') && str_contains($body, 'id="vendor-credits-tab-issued"'), 'the list: a card for the credit; tabs');
$d = screen($bea, '/vendor-credits/?status=void')[1];
ok(array_unique(array_column($d['vendor_credits'] ?? [], 'status')) === ['void'], 'status filters (JSON)');
$d = screen($bea, '/vendor-credits/' . $vc)[1];
ok(($d['vendor_credit']['number'] ?? '') === $row['number'] && ($d['vendor_credit']['bill']['number'] ?? '') === bill_row($bill)['number'] && count($d['vendor_credit']['lines'] ?? []) === 1 && isset($d['may']), 'JSON: the vendor credit with its bill and lines');
$body = page($carl, '/vendor-credits/' . $vc2 . '/edit')['body'];
ok(req('GET', '/vendor-credits/' . $vc . '/edit', ['jar' => $bea])['code'] === 422, 'the edit form of a void credit: 422');
$vc3 = (int) act($bea, '/vendor-credits/save.php', ['vendor' => $V, 'bill' => $bill, 'lines' => json_encode([['description' => 'Page check', 'quantity' => '1', 'unit_price' => '5.00']])])[1]['record_id'];
$body = page($carl, '/vendor-credits/' . $vc3)['body'];
ok(str_contains($body, 'id="vendor-credit-issue-btn"') && str_contains($body, 'id="vendor-credit-issue-apply"') && str_contains($body, 'Expense account') && str_contains($body, 'id="vendor-credit-line-new-save-btn"'), 'the draft page: the lines editor (Expense account), Issue with "applied at once"');
$body = page($bea, '/vendor-credits/' . $vc3)['body'];
ok(str_contains($body, 'id="vendor-credit-awaiting-note"') && !str_contains($body, 'id="vendor-credit-issue-btn"'), 'a Bookkeeper sees "awaiting issue", not Issue');
$body = page($vera, '/vendor-credits/' . $vc3)['body'];
ok(!str_contains($body, 'id="vendor-credit-actions"') && !str_contains($body, 'vendor-credit-line-new-save-btn'), 'a Viewer sees no actions and no editor');
finish();
